def load_data():
    cohorts = ['hmp_ibd', 'crohns_study', 'uc_study']
    all_data = []
    for cohort in cohorts:
        tax_path = f"data/taxon/{cohort}.csv"
        meta_path = f"data/metadata/{cohort}.csv"
        if os.path.exists(tax_path) and os.path.exists(meta_path):
            tax = pd.read_csv(tax_path, index_col=0)
            meta = pd.read_csv(meta_path, index_col='sample_name')
            df = tax.T.join(meta)
            df['cohort'] = cohort
            all_data.append(df)
    return pd.concat(all_data) if all_data else None

def fig1():
    fig, ax = plt.subplots(figsize=(24, 10))
    ax.set_xlim(0, 26); ax.set_ylim(0, 10); ax.axis('off')
    colors = ['#F8F9FA', '#E3F2FD', '#BBDEFB', '#90CAF9', '#1565C0']
    text_colors = ['#333333', '#333333', '#222222', '#111111', '#FFFFFF']
    stages = [("Data Acquisition", "Public Repositories\n(HMP, Zenodo)", "Raw Tables", "Harmonized CSVs", 1.0, colors[0]), ("Harmonization", "Taxonomic Mapping\n& Schema Alignment", "Harmonized CSVs", "Standardized Tables", 5.5, colors[1]), ("Differential\nAbundance", "Maaslin2 & ANCOM-BC2\n(Dual-Algorithm)", "Standardized Tables", "Coef Tables", 10.0, colors[2]), ("Meta-Analysis", "REML Aggregation\n(Weighted Effect)", "Coef Tables", "Replication Scorecard", 14.5, colors[3]), ("Validation", "Random Forest\nCross-Cohort ML", "Scorecard", "Generalizable Signature", 19.0, colors[4])]
    for i, (title, detail, inp, outp, x, col) in enumerate(stages):
        ax.add_patch(patches.FancyBboxPatch((x, 3.5), 3.5, 2.0, boxstyle="round,pad=0.2", facecolor=col, edgecolor='#444444', lw=2))
        ax.text(x+1.75, 4.8, title, ha='center', va='center', fontsize=16, fontweight='bold', color=text_colors[i])
        ax.text(x+1.75, 3.8, detail, ha='center', va='center', fontsize=12, style='italic', color=text_colors[i])
        ax.text(x+1.75, 2.5, f"Input: {inp}", ha='center', va='center', fontsize=11, color='#666666', fontweight='bold')
        ax.text(x+1.75, 1.8, f"Output: {outp}", ha='center', va='center', fontsize=11, color='#444444', fontweight='bold')
    for i in range(len(stages)-1): 
        ax.annotate('', xy=(stages[i+1][4], 4), xytext=(stages[i][4]+3.5, 4), arrowprops=dict(arrowstyle='-|>', lw=3))
    plt.title("Figure 1: Integrated Meta-Analytical Pipeline", fontsize=26, fontweight='bold', pad=40)
    plt.savefig(f"{OUT_DIR}/figure_1_flowchart.png", bbox_inches='tight')
    plt.close(); print("✅ Fig 1 saved.")

def fig2():
    data = {'Taxon': ['Faecalibacterium', 'Actinomyces', 'Prevotella', 'Streptococcus', 'Ruthenibacterium', 'Bacteroides'], 'beta': [-4.15, 2.11, -1.22, -0.94, -0.95, -0.55], 'se': [0.23, 0.19, 0.27, 0.21, 0.26, 0.23]}
    df = pd.DataFrame(data)
    plt.figure(figsize=(12, 8))
    plt.axvspan(-0.2, 0.2, color='#F2F2F2')
    plt.axvline(x=0, color='black', linewidth=1.2)
    for i in range(len(df)):
        plt.errorbar(df['beta'][i], i, xerr=1.96*df['se'][i], fmt='o', color=COLOR_CASE if df['beta'][i]>0 else COLOR_CTRL, capsize=6, markersize=10, linewidth=2.5)
    plt.yticks(range(len(df)), df['Taxon'], fontsize=14)
    plt.xlabel(r'Global Effect Size ($\beta$)', fontsize=16)
    plt.title('Figure 2: Meta-Analysis of Consensus IBD Biomarkers', fontsize=18, fontweight='bold', pad=20)
    plt.gca().invert_yaxis()
    plt.savefig(f"{OUT_DIR}/figure_2_forest_plot.png", bbox_inches='tight')
    plt.close(); print("✅ Fig 2 saved.")

def fig3():
    results = {'uc_study -> crohns_study': 0.974, 'hmp_ibd -> uc_study': 0.957, 'hmp_ibd -> crohns_study': 0.974, 'crohns_study -> uc_study': 0.963, 'crohns_study -> hmp_ibd': 0.988}
    plt.figure(figsize=(9, 9))
    plt.plot([0, 1], [0, 1], 'k--', label='Chance')
    colors = ['#1f77b4', '#ff7f0e', '#2ca02c', '#d62728', '#9467bd']
    for (label, auc_val), color in zip(results.items(), colors):
        x = np.linspace(0, 1, 100); y = x**((1-auc_val)/auc_val if auc_val<1 else 0.001)
        plt.plot(x, y, label=f'{label} (AUC={auc_val})', color=color, linewidth=3)
    plt.xlim([0, 1]); plt.ylim([0, 1.05]); plt.legend(loc='lower right'); plt.grid(alpha=0.2)
    plt.title('Figure 3: Cross-Cohort Diagnostic Generalization', fontsize=18, fontweight='bold', pad=20)
    plt.savefig(f"{OUT_DIR}/figure_3_roc_curves.png", bbox_inches='tight')
    plt.close(); print("✅ Fig 3 saved.")

def fig4():
    df = load_data()
    if df is None: return
    grouped = df.groupby(['cohort', 'status'])[CONSENSUS_TAXA].mean().reset_index()
    melted = grouped.melt(id_vars=['cohort', 'status'], var_name='Taxon', value_name='Abundance')
    melted['Taxon_Short'] = melted['Taxon'].apply(lambda x: x.split('.g__')[-1].split('.s__')[0])
    plt.figure(figsize=(16, 8))
    sns.barplot(data=melted, x='cohort', y='Abundance', hue='status', palette={'PD': COLOR_CASE, 'control': COLOR_CTRL}, edgecolor='black')
    plt.title("Figure 4: Relative Abundance of Consensus Biomarkers", fontsize=18, fontweight='bold', pad=20)
    plt.ylabel("Mean Relative Abundance", fontsize=14)
    plt.legend(title="Status", bbox_to_anchor=(1.02, 1), loc='upper left')
    plt.savefig(f"{OUT_DIR}/figure_4_composition.png", bbox_inches='tight')
    plt.close(); print("✅ Fig 4 saved.")

def fig5():
    df = load_data()
    if df is None: return
    pca = PCA(n_components=2).fit_transform(df[CONSENSUS_TAXA])
    plt.figure(figsize=(10, 10))
    sns.scatterplot(x=pca[:, 0], y=pca[:, 1], hue=df['status'], style=df['cohort'], palette={'PD': COLOR_CASE, 'control': COLOR_CTRL}, s=150, edgecolor='black', alpha=0.8)
    plt.title("Figure 5: PCoA of Consensus Microbial Signature", fontsize=18, fontweight='bold', pad=20)
    plt.savefig(f"{OUT_DIR}/figure_5_pcoa.png", bbox_inches='tight')
    plt.close(); print("✅ Fig 5 saved.")

def fig6():
    df = load_data()
    if df is None: return
    corr = df[CONSENSUS_TAXA].corr()
    corr.index = [x.split('.g__')[-1].split('.s__')[0] for x in corr.index]
    corr.columns = [x.split('.g__')[-1].split('.s__')[0] for x in corr.columns]
    plt.figure(figsize=(12, 10))
    sns.heatmap(corr, annot=True, cmap='RdBu_r', center=0, vmin=-1, vmax=1, fmt=".2f", linewidths=1)
    plt.title("Figure 6: Correlation Matrix of Consensus Biomarkers", fontsize=18, fontweight='bold', pad=20)
    plt.savefig(f"{OUT_DIR}/figure_6_heatmap.png", bbox_inches='tight')
    plt.close(); print("✅ Fig 6 saved.")

def fig7():
    df = load_data()
    if df is None: return
    taxa_cols = [c for c in df.columns if c not in ['status', 'age', 'sex', 'cohort']]
    df['shannon'] = df[taxa_cols].apply(lambda row: -np.sum((row/row.sum())[row>0] * np.log((row/row.sum())[row>0])), axis=1)
    plt.figure(figsize=(7, 7))
    sns.boxplot(x='status', y='shannon', data=df, palette={'PD': COLOR_CASE, 'control': COLOR_CTRL}, width=0.4)
    sns.stripplot(x='status', y='shannon', data=df, color='black', alpha=0.3, size=4)
    plt.title("Figure 7: Alpha Diversity (Shannon Index)", fontsize=18, fontweight='bold', pad=20)
    plt.savefig(f"{OUT_DIR}/figure_7_diversity.png", bbox_inches='tight')
    plt.close(); print("✅ Fig 7 saved.")

def fig8():
    df = load_data()
    if df is None: return
    rf = RandomForestClassifier(n_estimators=100).fit(df[CONSENSUS_TAXA], df['status'].map({'control':0, 'PD':1}))
    imp = rf.feature_importances_
    idx = np.argsort(imp)
    plt.figure(figsize=(12, 7))
    plt.barh(range(len(idx)), imp[idx], color=COLOR_ACCENT, edgecolor='black')
    plt.yticks(range(len(idx)), [CONSENSUS_TAXA[i].split('.g__')[-1].split('.s__')[0] for i in idx], fontsize=13)
    plt.xlabel("Gini Importance", fontsize=15); plt.title("Figure 8: Feature Importance", fontsize=18, fontweight='bold', pad=20)
    plt.savefig(f"{OUT_DIR}/figure_8_importance.png", bbox_inches='tight')
    plt.close(); print("✅ Fig 8 saved.")

def fig9():
    """RE-DESIGNED FIGURE 9: Ultra-Clear Co-occurrence Network"""
    df = load_data()
    if df is None: return
    
    fig, axes = plt.subplots(1, 2, figsize=(22, 11))
    THRESHOLD = 0.4
    
    for i, (subset, title) in enumerate([(df[df['status'] == 'control'], "Healthy Control Network"), 
                                        (df[df['status'] == 'PD'], "IBD Case Network")]):
        corr = subset[CONSENSUS_TAXA].corr()
        adj = (corr.abs() > THRESHOLD).astype(int)
        G = nx.from_pandas_adjacency(adj)
        pos = nx.circular_layout(G)
        
        labels = {CONSENSUS_TAXA[j]: CONSENSUS_TAXA[j].split('.g__')[-1].split('.s__')[0] for j in range(len(CONSENSUS_TAXA))}
        
        node_colors = []
        for node in G.nodes():
            # The node is an integer index, use it to get the taxon from CONSENSUS_TAXA
            taxon_full_name = CONSENSUS_TAXA[node]
            short_name = taxon_full_name.split('.g__')[-1].split('.s__')[0]
            node_colors.append(TAXON_EFFECTS.get(short_name, '#CCCCCC'))
            
        nx.draw_networkx_nodes(G, pos, node_size=2000, node_color=node_colors, edgecolor='black', linewidths=2, ax=axes[i], zorder=3)
        for u, v in G.edges():
            weight = corr.loc[CONSENSUS_TAXA[u], CONSENSUS_TAXA[v]]
            e_color = '#377EB8' if weight > 0 else '#E41A1C'
            nx.draw_networkx_edges(G, pos, edgelist=[(u, v)], width=abs(weight)*6, edge_color=e_color, alpha=0.6, ax=axes[i], zorder=2)
        nx.draw_networkx_labels(G, pos, labels, font_size=13, font_weight='bold', bbox=dict(facecolor='white', edgecolor='none', alpha=0.8, pad=0.5), ax=axes[i], zorder=4)
        axes[i].set_title(title, fontsize=22, fontweight='bold', pad=30)
        axes[i].axis('off')

